@extends('layouts.app') @section('heading',$product->exists?'Edit product':'Add product') @section('content')<form class="card form-grid" method="post" enctype="multipart/form-data" action="{{ $product->exists?route('products.update',$product):route('products.store') }}">@csrf @if($product->exists)@method('PUT')@endif<label>Product name<input name="name" value="{{ old('name',$product->name) }}" required></label><label>SKU<input name="sku" value="{{ old('sku',$product->sku) }}"></label><label>Category<select name="category_id"><option value="">Uncategorized</option>@foreach($categories as $c)<option value="{{ $c->id }}" @selected(old('category_id',$product->category_id)==$c->id)>{{ $c->name }}</option>@endforeach</select></label><label>Supplier<select name="supplier_id"><option value="">None</option>@foreach($suppliers as $s)<option value="{{ $s->id }}" @selected(old('supplier_id',$product->supplier_id)==$s->id)>{{ $s->name }}</option>@endforeach</select></label><label>Price<input type="number" step=".01" min="0" name="price" value="{{ old('price',$product->price) }}" required></label><label>Quantity<input type="number" min="0" name="quantity" value="{{ old('quantity',$product->quantity??0) }}" required></label><label>Low-stock level<input type="number" min="0" name="low_stock_level" value="{{ old('low_stock_level',$product->low_stock_level??5) }}" required></label><label>Expiration date<input type="date" name="expiration_date" value="{{ old('expiration_date',$product->expiration_date?->format('Y-m-d')) }}"></label><label class="full">Product image<input type="file" name="image" accept="image/*"></label><div class="full row"><button class="btn primary">Save product</button><a class="btn" href="{{ route('products.index') }}">Cancel</a></div></form>@endsection
